declare(strict_types=1);require __DIR__.'/bootstrap.php';use Ogpn\Bot\{Bootstrap,Auth,Domain};$pdo=Bootstrap::pdo();$w=Auth::worker($pdo,'discovery.ingest');$b=json_decode(file_get_contents('php://input'),true);if(!is_array($b)||!isset($b['job_id'],$b['urls']))Bootstrap::json(['error'=>'invalid_payload'],422);$domains=[];foreach((array)$b['urls'] as $url){if(is_string($url)&&($d=Domain::fromUrl($url)))$domains[$d]=Domain::tld($d);} $pdo->beginTransaction();$ins=$pdo->prepare("INSERT INTO domain_queue(domain,tld,last_seen_at) VALUES(?,?,UTC_TIMESTAMP()) ON DUPLICATE KEY UPDATE last_seen_at=UTC_TIMESTAMP(),common_crawl_seen_count=common_crawl_seen_count+1");$added=0;foreach($domains as $d=>$t){$ins->execute([$d,$t]);$added+=$ins->rowCount()===1?1:0;} $u=$pdo->prepare("UPDATE common_crawl_jobs SET status='completed',reserved_by=NULL,reserved_until=NULL,rows_received=?,root_domains_found=?,domains_added=?,duration_ms=? WHERE id=? AND reserved_by=?");$u->execute([(int)($b['rows_received']??count($b['urls'])),count($domains),$added,(int)($b['duration_ms']??0),(int)$b['job_id'],$w['worker_id']]);$pdo->commit();Bootstrap::json(['ok'=>true,'root_domains'=>count($domains),'domains_added'=>$added]);
